def is_latin_square(subset):
    n = len(subset)
    for i in range(n):
        seen = set()
        for j in range(n):
            if subset[j][i] in seen:
                return False
            seen.add(subset[j][i])
    return True

def find_good_subset(arrays, n):
    for subset in range(1, 2**n):
        subset_arrays = [arrays[i] for i in range(2*n) if (subset & (1 << i))]
        if is_latin_square(subset_arrays):
            return subset_arrays
    return None

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        arrays = []
        for _ in range(2*n):
            array = list(map(int, data[index:index+n]))
            arrays.append(array)
            index += n

        good_subset = find_good_subset(arrays, n)
        if good_subset:
            result = [i + 1 for i in range(2*n) if (subset & (1 << i))]
            results.append(result)

    for result in results:
        print(len(result))
        print(" ".join(map(str, result)))

